package com.eye.plan;
import com.eye.core.*;import java.nio.file.*;import java.time.*;import java.util.*;
public class PlanRefactorAcceptance {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[] args)throws Exception{
 System.setProperty("user.home",Files.createTempDirectory("EyeRelax-plan-refactor-").toString());
 Properties legacy=new Properties();legacy.setProperty("planned","3");legacy.setProperty("remain.id","2");check(PlanPropertiesCodec.readPlannedSeconds(legacy,"",0)==180,"legacy planned minutes");check(PlanPropertiesCodec.readRemainingSeconds(legacy,"id",0)==120,"legacy remaining minutes");legacy.setProperty("plannedSeconds","97");check(PlanPropertiesCodec.readPlannedSeconds(legacy,"",0)==97,"exact seconds override");
 PlanItem item=new PlanItem("id","中文计划",97,42);item.createdDate=LocalDate.of(2026,10,5);item.kind=PlanItem.PlanKind.RECURRING;item.recurringRule=PlanItem.RecurringRule.BY_WEEKDAY;item.weekdays=new LinkedHashSet<>(Set.of(2,4));item.completedAtEpochMs=12345;item.completedZoneId="Asia/Shanghai";Properties snapshot=new Properties();PlanPropertiesCodec.writePlanSnapshot(snapshot,"snapshot.id.",item);var read=PlanPropertiesCodec.readSnapshot(snapshot,"snapshot.id.","id",LocalDate.of(2020,1,1));check(read.plannedSeconds==97&&read.name.equals(item.name)&&read.weekdays.equals(item.weekdays)&&read.completedAtEpochMs==12345,"snapshot roundtrip");
 var holidays=new HashSet<LocalDate>();var schedule=new PlanSchedule(holidays);LocalDate monday=LocalDate.of(2026,10,5);item.recurringRule=PlanItem.RecurringRule.WEEKDAY;check(schedule.collectOccurrences(item,monday,monday.plusDays(6)).size()==5,"workdays");holidays.add(monday);check(schedule.collectOccurrences(item,monday,monday.plusDays(6)).size()==4,"custom holiday");item.recurringRule=PlanItem.RecurringRule.HOLIDAY;check(schedule.collectOccurrences(item,monday,monday.plusDays(6)).size()==3,"holiday and weekend");item.recurringRule=PlanItem.RecurringRule.BY_WEEKDAY;check(schedule.collectOccurrences(item,monday,monday.plusDays(6)).size()==2,"selected weekdays");item.kind=PlanItem.PlanKind.MULTI_DAY;item.selectedDates=new LinkedHashSet<>(Set.of(monday,monday.plusDays(3)));check(schedule.collectOccurrences(item,monday,monday.plusDays(6)).equals(List.of(monday,monday.plusDays(3))),"multi-day ordered");check(schedule.collectOccurrences(item,monday.plusDays(8),monday).isEmpty(),"reverse range");
 var config=new Config();var manager=new PlanManager(config);manager.loadToday();var plan=manager.addPlan("重构兼容",90,PlanItem.PlanKind.RECURRING,PlanItem.RecurringRule.EVERY_DAY,Set.of(),Set.of());manager.consumeSeconds(plan.id,61);var reloaded=new PlanManager(config);reloaded.loadToday();check(reloaded.getRemainingSeconds(plan.id)==29,"progress reload");reloaded.updatePlan(plan.id,"修改后",120,PlanItem.PlanKind.RECURRING,PlanItem.RecurringRule.EVERY_DAY,Set.of(),Set.of());check(reloaded.getRemainingSeconds(plan.id)==59,"edit preserves elapsed");reloaded.deletePlan(plan.id);check(reloaded.get(plan.id)==null,"delete");System.out.println("PASS legacy/exact property compatibility, snapshot roundtrip, recurrence rules, holidays, ordered dates, persisted progress and edit/delete");
 }
}
